def local_panel_html():
    """Reuse the project panel over its authenticated same-origin HTTP bridge."""
    transport = r'''const launchMode='local';
const localSession=crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24)),v=>v.toString(16).padStart(2,'0')).join('');
const localBridge=async(method,params,timeout)=>{
 if(method!=='tools/call'||!['learning_panel_open','learning_panel_direct_action'].includes(params?.name))throw Error('unsupported local request');
 const opening=params.name==='learning_panel_open',controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
 try{const response=await fetch(opening?'/api/bootstrap':'/api/action',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...params.arguments,ui_session_id:localSession}),signal:controller.signal});
 const data=await response.json();return {content:[],...(!response.ok?{isError:true}:{}),_meta:{agentLearningPanel:{...data,scope:'project'}}};
 }catch(error){if(error?.name==='AbortError')throw {code:'timeout'};throw error;}finally{clearTimeout(timer);}
};'''
    return HTML.replace("const launchMode='legacy',localBridge=null;", transport)


